def solution():
    # We are looking for lattice points (x, y, z) such that x^2 + y^2 + z^2 = 9
    # where x, y, z are integers.

    count = 0
    # We only need to check values from -3 to 3 because the square of any number
    # outside this range would exceed 9.

    for x in range(-3, 4):
        for y in range(-3, 4):
            for z in range(-3, 4):
                if x*x + y*y + z*z == 9:
                    count += 1

    return count

answer = solution()
